//
// Open Sans Regular y Bold (fuentes/*.ttf) en base64 para el PDF del
// presupuesto. Generado desde los .ttf de esta carpeta; si cambian, regenerar.

function decodificar(b64: string): Uint8Array {
  const bin = atob(b64);
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

export const openSansRegular = (): Uint8Array => decodificar(REGULAR);
export const openSansBold = (): Uint8Array => decodificar(BOLD);

const REGULAR = '';
const BOLD = '';
